/**
 * Bubble Sort Algorithm Implementation
 * 
 * This function sorts an array of integers in ascending order using the Bubble Sort algorithm.
 * It includes input validation and error handling as per the specified constraints.
 * 
 * Constraints:
 * - Input array must have a maximum length of 100 elements.
 * - Each element must be an integer between -10,000 and 10,000.
 * 
 * Time Complexity: O(n^2) in worst and average cases, O(n) in best case (when array is already sorted).
 * Space Complexity: O(1) - sorting is done in-place.
 * 
 * @param {number[]} arr - The array of integers to be sorted.
 * @returns {number[]} - The sorted array.
 * @throws {Error} - If input validation fails.
 */
function bubbleSort(arr) {
    // Input validation
    if (!Array.isArray(arr)) {
        throw new Error('Input must be an array.');
    }

    const maxLength = 100;
    if (arr.length > maxLength) {
        throw new Error(`Array length exceeds maximum allowed length of ${maxLength}.`);
    }

    const minValue = -10000;
    const maxValue = 10000;

    for (let i = 0; i < arr.length; i++) {
        if (!Number.isInteger(arr[i])) {
            throw new Error(`Element at index ${i} is not an integer.`);
        }
        if (arr[i] < minValue || arr[i] > maxValue) {
            throw new Error(`Element at index ${i} is out of range (must be between ${minValue} and ${maxValue}).`);
        }
    }

    // Bubble Sort implementation
    const n = arr.length;
    let swapped; // Flag to check if any swap occurred in a pass

    // Outer loop: runs n-1 times
    for (let i = 0; i < n - 1; i++) {
        swapped = false; // Reset swap flag for each pass

        // Inner loop: compares adjacent elements and swaps if they are in wrong order
        // After each pass, the largest element "bubbles up" to the end
        for (let j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                // Swap elements if they are in wrong order
                [arr[j], arr[j + 1]] = [arr[j + 1], arr[j]];
                swapped = true; // Mark that a swap occurred
            }
        }

        // Optimization: if no swaps occurred in this pass, the array is already sorted
        if (!swapped) {
            break;
        }
    }

    return arr;
}

// Example usage and testing
try {
    const unsortedArray = [64, 34, 25, 12, 22, 11, 90];
    const sortedArray = bubbleSort(unsortedArray);
    console.log('Sorted array:', sortedArray);
} catch (error) {
    console.error('Error:', error.message);
}
